import type { VehicleDNA, VehicleSource } from './vehicle-dna';

interface ExpansionProfile {
    id: number;
    brand: string;
    model: string;
    year: string;
    chassisCode: string;
    summary: string;
    phases: Array<{ years: string; name: string; summary: string }>;
    engines: string[];
    strengths: string[];
    weaknesses: string[];
    checks: Array<{ title: string; severity: 'medium' | 'high'; detail: string }>;
    sources: VehicleSource[];
    verdict: string;
}

const officialAudiHistory = 'https://www.audi-mediacenter.com/en/publications/more/audi-tradition-anniversary-dates-2026-1676/download';
const officialAudiA4History = 'https://www.audi-mediacenter.com/en/press-releases/silver-jubilee-audi-a4-celebrates-its-25th-birthday-11619/download';
const officialAudiQ3 = 'https://www.audi-mediacenter.com/en/press-releases/one-millionth-audi-q3-made-in-gyor-16669/download';
const officialToyotaModels = 'https://global.toyota/en/mobility/toyota-brand/gallery/';
const officialHondaArchive = 'https://global.honda/en/newsroom/';

function buildVehicle(profile: ExpansionProfile): VehicleDNA {
    const issueBase = profile.id * 100;
    return {
        id: profile.id,
        brand: profile.brand,
        model: profile.model,
        year: profile.year,
        dnaScore: 78,
        strengths: profile.strengths,
        weaknesses: profile.weaknesses,
        chronicIssues: profile.checks.map((check, index) => ({
            id: issueBase + index + 1,
            title: check.title,
            severity: check.severity,
            reportCount: 0,
            description: `${check.detail} Bu başlık kesin arıza iddiası değil, ${profile.model} satın alma kontrol noktasıdır; VIN, bakım belgesi, soğuk-sıcak test ve modele uygun teşhis verisi birlikte değerlendirilmelidir.`,
        })),
        userExperiences: [],
        totalReports: 0,
        generationInfo: {
            chassisCode: profile.chassisCode,
            marketScope: `Türkiye ikinci elinde ${profile.year} model yılı odağı`,
            summary: profile.summary,
            phases: profile.phases,
            bodyStyles: profile.model.includes('Q') || profile.model.includes('CR-V') || profile.model.includes('Cross') || profile.model.includes('C-HR') ? ['5 kapı SUV/crossover'] : ['Sedan/hatchback; pazara ve nesle göre gövde seçeneği'],
            turkeyEngines: profile.engines,
        },
        sources: profile.sources,
        buyingGuide: {
            summary: `${profile.summary} İlan adı yerine VIN’den motor, şanzıman, üretim tarihi ve fabrika donanımı doğrulanmalıdır.`,
            idealFor: profile.strengths.slice(0, 3),
            inspectionSteps: [
                { title: 'VIN ve nesil', description: 'Kasa kodu, üretim fazı, motor, şanzıman ve fabrika donanımını doğrulayın.' },
                { title: 'Soğuk kontrol', description: profile.checks[0].detail },
                { title: 'Güç aktarımı', description: profile.checks[1].detail },
                { title: 'Elektronik/güvenlik', description: profile.checks[2].detail },
                { title: 'Uzun test', description: 'En az 30 dakika şehir içi, yokuş, bozuk zemin ve sabit hız testi yapıp sıcak tekrar kontrolü uygulayın.' },
            ],
            finalVerdict: profile.verdict,
        },
        faqs: [
            { question: `${profile.model} hangi yılları kapsar?`, answer: `Bu sayfadaki nesil ${profile.year} dönemini kapsar. Üretim, model ve ilk tescil tarihi farklı olabileceği için VIN esas alınmalıdır.` },
            { question: `${profile.model} alırken en önemli kontrol nedir?`, answer: `${profile.checks[0].title}, ${profile.checks[1].title.toLocaleLowerCase('tr-TR')} ve geçmiş kayıtlarının birbirini doğrulaması önceliklidir.` },
            { question: `${profile.model} motor seçenekleri nelerdir?`, answer: `Türkiye ve yakın Avrupa pazarlarında öne çıkan seçenekler: ${profile.engines.join(', ')}. Kesin kombinasyon VIN ve ruhsattan doğrulanmalıdır.` },
            { question: `${profile.model} alınır mı?`, answer: profile.verdict },
        ],
    };
}

